xql_query:
// ============================================================
// Rule: CTX_Potential Browser Credential and Session Cookie Theft
// Vendor: Cortex
// Objective:
// Detect activity associated with CTX_Potential Browser Credential and Session Cookie Theft.
// Severity: SEV_040_HIGH
// Category: EXFILTRATION
// ============================================================
// MITRE ATT&CK:
// Tactic: TA0006 - Credential Access
// Technique: T1555.003 - Credentials from Password Stores: Credentials from Web Browsers

// Configuração inicial: comparações não diferenciam maiúsculas/minúsculas
// Objetivo: evitar perda de eventos por variações de caixa nos nomes de processos e arquivos
config case_sensitive = false

// Fonte de dados: telemetria do agente Cortex XDR
| dataset = xdr_data

// Filtro: restringe a eventos de encerramento de processos
// PROCESS_STOP = processo finalizado no endpoint
| filter event_type = ENUM.PROCESS
| filter event_sub_type = ENUM.PROCESS_STOP

// Filtro: monitora o encerramento dos principais navegadores baseados em Chromium
| filter action_process_image_name in (
    "chrome.exe",
    "msedge.exe",
    "brave.exe"
)

// Filtro: ignora encerramentos realizados pelo próprio navegador
// Objetivo: identificar processos externos encerrando Chrome, Edge ou Brave
| filter actor_process_image_name !~= "(^msedge|^chrome|^brave)"

// Seleção e normalização dos campos do evento de processo
// - init_process_name: processo responsável pelo encerramento do navegador
// - browser_name: navegador que foi encerrado
| fields
    _time,
    agent_hostname,
    agent_id,
    actor_process_image_name as init_process_name,
    actor_process_command_line as init_process_command_line,
    action_process_image_name as browser_name

// Correlação: procura eventos de criação ou escrita de arquivos associados a infostealers
| join type = inner (

    // Fonte de dados: telemetria de arquivos do agente Cortex XDR
    dataset = xdr_data

    // Filtro: restringe a eventos de criação ou escrita em arquivos
    | filter event_type = ENUM.FILE
    | filter event_sub_type in (
        ENUM.FILE_CREATE_NEW,
        ENUM.FILE_WRITE
    )

    // Filtro: procura artefatos normalmente associados à extração de credenciais e cookies
    // - abe_decrypt.dll: possível componente utilizado para contornar App-Bound Encryption
    // - passwords.json: possível exportação de credenciais de navegadores
    // - cookies.json: possível exportação de cookies e sessões autenticadas
    | filter action_file_path ~= "abe_decrypt\\.dll|passwords\\.json|cookies\\.json"

    // Seleção e normalização dos campos do evento de arquivo
    | fields
        _time as file_time,
        agent_id as file_agent_id,
        actor_process_image_name as file_actor_process,
        action_file_name as file_name,
        action_file_path as file_path

) as file_create (
    // Condição de correlação:
    // - mesmo endpoint
    // - mesmo nome de processo responsável pelos dois comportamentos
    file_create.file_agent_id = agent_id
    and file_create.file_actor_process = init_process_name
)

// Cálculo temporal: mede a diferença entre o encerramento do navegador
// e a criação/escrita do arquivo suspeito
| alter
    time_diff_seconds = timestamp_diff(file_time, _time, "SECOND")

// Janela temporal da correlação:
// - aceita arquivo criado até 60 segundos antes do encerramento do navegador
// - aceita arquivo criado até 10 minutos depois
// Objetivo: compensar diferenças de ordem e atraso na ingestão dos eventos
| filter time_diff_seconds >= -60
| filter time_diff_seconds <= 600

// Resultado final: apresenta as principais evidências para investigação
| fields
    agent_hostname,
    _time,
    init_process_name,
    init_process_command_line,
    browser_name,
    file_time,
    file_actor_process,
    file_name,
    file_path,
    time_diff_seconds

// Ordenação: apresenta primeiro os eventos mais recentes
| sort desc _time
